#!/usr/bin/env bash
# Print the Homebrew formula for a qget release.
#   scripts/homebrew-formula.sh v0.2.0 SHA256SUMS > Formula/qget.rb
set -euo pipefail
tag="${1:?usage: homebrew-formula.sh <tag> <SHA256SUMS>}"
sums="${2:?usage: homebrew-formula.sh <tag> <SHA256SUMS>}"
version="${tag#v}"
base="https://github.com/dharrsan-hq/qget/releases/download/$tag"

sha() {
  local name="qget-$tag-$1.tar.gz"
  local s
  s=$(awk -v n="$name" '$2 == n || $2 == "*"n {print $1}' "$sums")
  [[ -n "$s" ]] || { echo "missing checksum for $name" >&2; exit 1; }
  echo "$s"
}

cat <<EOF
# Generated by scripts/homebrew-formula.sh from the $tag release. Do not edit.
class Qget < Formula
  desc "Fast, verified, resumable downloads with parallel stream-extraction"
  homepage "https://github.com/dharrsan-hq/qget"
  version "$version"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$base/qget-$tag-macos-aarch64.tar.gz"
      sha256 "$(sha macos-aarch64)"
    end
    on_intel do
      url "$base/qget-$tag-macos-x86_64.tar.gz"
      sha256 "$(sha macos-x86_64)"
    end
  end

  on_linux do
    on_arm do
      url "$base/qget-$tag-linux-aarch64.tar.gz"
      sha256 "$(sha linux-aarch64)"
    end
    on_intel do
      url "$base/qget-$tag-linux-x86_64.tar.gz"
      sha256 "$(sha linux-x86_64)"
    end
  end

  def install
    bin.install "qget"
    man1.install "qget.1"
    bash_completion.install "qget.bash" => "qget"
    zsh_completion.install "_qget"
    fish_completion.install "qget.fish"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/qget --version")
    (testpath/"abc.txt").write "abc"
    assert_match "sha256:ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
                 shell_output("#{bin}/qget hash --algo sha256 #{testpath}/abc.txt")
  end
end
EOF
